package com.example.godmace.commands; import org.bukkit.Location; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*; public class EndFightCommand implements CommandExecutor, TabCompleter { private Location loc = null; private List<Player> q = new ArrayList<>(); @Override public boolean onCommand(CommandSender s, Command c, String l, String[] a) { if(s instanceof Player p && p.isOp() && a.length>0) { switch(a[0].toLowerCase()){ case "set": loc=p.getLocation(); break; case "join": if(!q.contains(p)) q.add(p); break; case "start": if(loc!=null) { for(Player t:q) t.teleport(loc); q.clear(); } break; } } return true; } @Override public List<String> onTabComplete(CommandSender s, Command c, String l, String[] a) { return a.length==1?Arrays.asList("set","join","start"):new ArrayList<>(); } }